DECLARE
  entries jsonb := $design_catalog_01dda70a2b759564$[{"manifest":{"slug":"background-removal","name":"背景去除与透明素材","description":"去除已有图片背景并保留原始资产，使用已配置的 gpt-image-2 API 输出透明 PNG；区分生成素材透明处理与画板透明导出。","version":"2.0.0","category":"design","iconName":"scissors","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"image","intents":["background-removal","cutout","transparent-background"],"outputKinds":["transparent-png"],"requiredTools":["generate_image","confirm_image_generation"],"optionalTools":["inspect_design","get_design_objects","update_design_brief","verify_design_result","get_brand_kit"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]},{"role":"image","required":true,"preferredIds":["gpt-image-2"],"exactIds":["gpt-image-2"]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","使用 generate_image.operation=remove_background、单张原图、PNG 与恰为 gpt-image-2 的工作区模型，经用户确认后执行持久化任务。不得换成 all/vip。","API 抠图可能改变主体细节，不保证产品标签、文字、纹理逐像素保真；alpha 校验不等于视觉质量验收。","当前执行器固定 hd 质量并保留所有前景，不支持用 prompt 指定局部主体或交互蒙版。"],"examples":["只去掉这张产品照片的背景，产品和标签不能变。"],"sources":[{"title":"OpenAI Image generation：透明背景与图像编辑","url":"https://developers.openai.com/api/docs/guides/image-generation","relation":"inspired-by"}]}}},"content":"---\nname: background-removal\ndescription: 去除已有图片背景并保留原始资产，使用已配置的 gpt-image-2 API 输出透明 PNG；区分生成素材透明处理与画板透明导出。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 背景去除与透明素材\n\n先区分三种请求：已有图片主体分离、新生成素材要透明、画板导出透明。保留当前目标和原始资产，明确要保留的主体；头发、玻璃、白色产品和孔洞需要实际预览才能判定效果。\n\n已有图片使用 generate_image 的 operation=remove_background，必须传入一张已解析的原图和 outputFormat=png，当前固定 quality=hd。根据当前工作区目录选择上游模型恰为 gpt-image-2 的公开模型 ID；gpt-image-2-all/vip 不是替代。该流程走既有生成方案、用户确认、持久化任务和结果回填，不能把方案已创建说成抠图已完成。执行依赖或精确模型不可用时如实说明，不退回普通文生图，也不下载模型。\n\n去背景模式由服务端发送透明背景参数并验证 PNG/alpha，按固定指令保留所有前景，不支持借助 prompt 只选择某个主体或指定蒙版；普通 generate 模式的 outputFormat=png 本身不保证透明。API 编辑可能改变主体文字、纹理与边缘，不是逐像素分割。用户明确要求产品标签或原图像素完全不变时，先说明此能力限制，不把这个 API 描述为无损方案。原生设计中的非背景生成图按平台已有流程处理，不追加重复抠图。export_design.transparent 只影响导出底色，不去掉像素内背景。按任务需要读 [透明处理边界](references/workflow.md)。\n\n## Loomic 范围\n\n只建议/分析时不调用写入或生成。后续若用户要求落地，使用当前真实目标、工具与模型；update_design_brief 可用时合并仍有效的保留项和最新纠正。已禁用技能、用户权限、目标锁和付费确认不能由本说明绕过。未收到实际图像不声称视觉验收；不存在的工具不能靠提示词补齐。\n","files":[{"file_path":"references/workflow.md","content":"# 背景去除与透明素材：按需细则\n\n## 原图抠图\n确认是哪个 image/canvas_image 与源 assetId，不能把预览缩略图或上次生成结果当源图。调用 generate_image 时明确 operation=remove_background、inputImages=[原图]、outputFormat=png，并从工作区目录选 upstreamModelId 恰为 gpt-image-2 的模型 ID。不存在该模型或任务服务时停止；不使用 gpt-image-2-all/vip，也不把原图丢弃退化成普通生成。\n\n独立画布图片通常在原图旁生成新图片，保留原始资产；如果本轮绑定了原生设计目标，先读取目标、版本与源图对象，使用该设计的真实 target，不能意外写入其他画板或替换背景层。只有用户明确要求替换原对象时设置 replace_object_id。生成方案后复述保留主体与 API 细节风险，复用 confirm_image_generation 在用户明确确认后执行。失败不得自行换模型或重启付费任务；异步 processing 也不等于失败。\n\n## 原生背景与导出\ncanvas.background=null 或透明 PNG 只处理画布底色；全幅背景图层和照片内背景仍会存在。删除背景层是设计对象变更，应遵守目标范围与确认，不能把 opacity=0/几何 mask 当作主体分割。\n\n## 质量与费用\n透明边缘、半透明主体、阴影保留需看真实结果。API 不是逐像素抠图，产品标签、文字和纹理可能被重绘；严格原样保真应明确告知限制，不能把调用成功等同于视觉验收。服务端的 alpha 校验只证明有透明像素，不证明边缘质量。处理错误不能擅自付费重画或增加其他模型；保留原图并说明未达标位置。没有实际预览证据就不能声称“已抠干净”。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"brand-consistency","name":"品牌一致性","description":"依据已绑定 Brand Kit 或用户批准规范保持设计一致；不擅自重做品牌，也不修改品牌套件。","version":"2.0.0","category":"design","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"native","intents":["brand","brand-consistency","brand-kit"],"outputKinds":["native-design","design-review"],"requiredTools":["inspect_design","get_design_objects","manipulate_design"],"optionalTools":["list_designs","update_design_brief","verify_design_result","get_brand_kit","search_design_resources"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","只使用已存在且获授权的原生画板；当前没有 Agent 自动创建多画板、任意 SVG 路径写入或 SVG/PDF 导出。"],"examples":["沿用我们的 Logo、字体和蓝色，只统一这张海报的层级。"],"sources":[{"title":"Brand rules as reusable constraints","url":"https://github.com/anthropics/skills/blob/main/skills/brand-guidelines/SKILL.md","license":"Apache-2.0","relation":"inspired-by"},{"title":"Reusable theme tokens","url":"https://github.com/anthropics/skills/blob/main/skills/theme-factory/SKILL.md","license":"Apache-2.0","relation":"inspired-by"}]}}},"content":"---\nname: brand-consistency\ndescription: 依据已绑定 Brand Kit 或用户批准规范保持设计一致；不擅自重做品牌，也不修改品牌套件。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 品牌一致性\n\n若 get_brand_kit 在本轮工具列表中可用，读取当前绑定套件；否则沿用用户给定规范，不声称已取到品牌库。区分正式规则、本轮明确覆盖项与参考图推测；冲突只询问影响结果的部分。\n\n建立固定 token：准确品牌名、Logo 比例与保护空间、主辅色、字体角色、图像语言；布局和信息可以随媒介变化。正式标识复用原资产，不通过生图重画；字体名不代表字体已加载。\n\n只对目标对象做满足品牌要求的改动，不连带改套件或其他画板。具体应用读 [品牌 token 方法](references/workflow.md)。\n\n## Loomic 执行边界\n\n只在用户要求实际修改时写入。已绑定任务先合并 goal/corrections；update_design_brief 可用时记录 goal、preserve、changes、acceptance 与真正阻断的 questions。明确小改直接执行，不再开展通用问卷。\n\n使用已绑定的 design_id；未绑定且用户指向已有画板时可用 list_designs 查找。inspect_design 取得 revision 与对象摘要，再用 get_design_objects 读取相关完整对象（每次最多 10 个）。manipulate_design 带最新 expected_revision、idempotency_key；局部 object.update 使用读取到的 object_id、expected_object_version 和 patch.object_type。读取对象为 camelCase，更新 patch 用 snake_case（如 font_size、font_weight），颜色用 {kind:\"solid\",color:\"#…\"}，不能直接套 Fabric 私有字段。\n\n保留未授权对象与属性；不要用 scene.replace、删除重建或 manipulate_canvas 绕过局部编辑。用户修正导致旧任务过期时停止旧操作。最后一次修改后再次核对实际内容差异；verify_design_result 可用时检查当前保存和预览，布局/图片工作用 visual=true，简单改字可 visual=false。视觉不可用、预览未同步、任务仍处理时如实说明，不把版本增加当成功或自动付费重试。\n","files":[{"file_path":"references/workflow.md","content":"# 品牌一致性：按需细则\n\n## 不变与可变\n固定身份：官方资产、品牌拼写、色彩角色、已确认字体；可变编排：内容优先级、留白、裁切、响应尺寸。允许用户为本次活动指定不同配色，不以品牌规则自动否定明确授权的本轮例外；记录例外，不写回套件。\n\n## 证据\n品牌工具可能给 URL、说明和字体名称，不一定有原生 assetObjectId/fontFaceId。只用实际取得的 ID 插入或绑定，缺元数据时请用户在资源面板选择。Logo 变形/安全空间需看实际预览；机器颜色对比不能替代视觉判断。没有可靠原标时不宣称已经准确复刻。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"campaign-design","name":"活动海报与宣传图","description":"设计活动海报、推广封面、广告和行动引导，组织准确文案与主视觉；已有定稿小改不重新策划。","version":"2.0.0","category":"design","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"hybrid","intents":["campaign","poster","promotion","cover"],"outputKinds":["native-design","design-brief"],"requiredTools":["inspect_design","get_design_objects","manipulate_design"],"optionalTools":["list_designs","update_design_brief","verify_design_result","get_brand_kit","search_design_resources","generate_image","get_image_proposal","confirm_image_generation"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]},{"role":"image","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","只使用已存在且获授权的原生画板；当前没有 Agent 自动创建多画板、任意 SVG 路径写入或 SVG/PDF 导出。"],"examples":["把活动时间和报名入口排成清晰的竖版宣传海报。"],"sources":[{"title":"Cover art-direction dimensions","url":"https://github.com/JimLiu/baoyu-skills/blob/main/skills/baoyu-cover-image/SKILL.md","license":"MIT","relation":"inspired-by"},{"title":"Composition and refinement method","url":"https://github.com/anthropics/skills/blob/main/skills/canvas-design/SKILL.md","license":"Apache-2.0","relation":"inspired-by"}]}}},"content":"---\nname: campaign-design\ndescription: 设计活动海报、推广封面、广告和行动引导，组织准确文案与主视觉；已有定稿小改不重新策划。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 活动海报与宣传图\n\n从用户事实提取受众、核心消息、投放尺寸、准确日期价格和行动入口，不编造折扣、销量、认证。信息足够即执行，非关键未知可说明假设；只有会改变方向或承诺真实性的缺口才询问。\n\n先决定第一眼的主信息、第二层解释和最后行动。用产品主导、文字主导或场景主导等不同组织方式解释选择，不能只说“更高级”。主图、背景和文案分层，准确文字用原生 text/textbox；素材生成只覆盖需要位图的部分，并遵守产品预算确认。\n\n针对构图、CTA 和跨尺寸变化读 [宣传版式方法](references/workflow.md)。\n\n## Loomic 执行边界\n\n只在用户要求实际修改时写入。已绑定任务先合并 goal/corrections；update_design_brief 可用时记录 goal、preserve、changes、acceptance 与真正阻断的 questions。明确小改直接执行，不再开展通用问卷。\n\n使用已绑定的 design_id；未绑定且用户指向已有画板时可用 list_designs 查找。inspect_design 取得 revision 与对象摘要，再用 get_design_objects 读取相关完整对象（每次最多 10 个）。manipulate_design 带最新 expected_revision、idempotency_key；局部 object.update 使用读取到的 object_id、expected_object_version 和 patch.object_type。读取对象为 camelCase，更新 patch 用 snake_case（如 font_size、font_weight），颜色用 {kind:\"solid\",color:\"#…\"}，不能直接套 Fabric 私有字段。\n\n保留未授权对象与属性；不要用 scene.replace、删除重建或 manipulate_canvas 绕过局部编辑。用户修正导致旧任务过期时停止旧操作。最后一次修改后再次核对实际内容差异；verify_design_result 可用时检查当前保存和预览，布局/图片工作用 visual=true，简单改字可 visual=false。视觉不可用、预览未同步、任务仍处理时如实说明，不把版本增加当成功或自动付费重试。\n","files":[{"file_path":"references/workflow.md","content":"# 活动海报与宣传图：按需细则\n\n## 美术方向\n分别决定主视觉的表达方式、配色角色、材质/渲染、文字密度和情绪强度。它们是可独立调整的变量，不是每次必须填写的问卷。已有品牌优先；新建时用一组主色、对比色、辅助文字色控制焦点。\n\n## 信息落位\n标题表达一个主张，细则承接证据或限制，CTA 明确“做什么/去哪做”。二维码或链接缺素材时不要生成看似可扫码的假码。标题、价格、日期、入口必须与定稿逐字核对。\n\n## 适配\n方图、横幅和竖图分别重排焦点、裁切与行数，不将整图非等比拉伸。不默认增做多个尺寸；只报告有对应真实设计/任务的交付。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"canvas-design","name":"原生画板设计","description":"在 Loomic 原生画板创作或重排海报、封面和静态视觉；保留可编辑图层，不生成 Python/HTML 来替代画板。","version":"2.0.0","category":"design","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"native","intents":["native-design","poster","composition"],"outputKinds":["native-design"],"requiredTools":["inspect_design","get_design_objects","manipulate_design"],"optionalTools":["list_designs","update_design_brief","verify_design_result","get_brand_kit","search_design_resources"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","只使用已存在且获授权的原生画板；当前没有 Agent 自动创建多画板、任意 SVG 路径写入或 SVG/PDF 导出。","保留的历史 canvas-fonts 及其许可不代表已加载到工作区字体库；本版本不使用 Python/Pillow/reportlab。"],"examples":["在这个空白画板上制作极简音乐节海报，保留给定日期。"],"sources":[{"title":"Composition and refinement method","url":"https://github.com/anthropics/skills/blob/main/skills/canvas-design/SKILL.md","license":"Apache-2.0","relation":"inspired-by"},{"title":"Bounded design critique","url":"https://github.com/pbakaus/impeccable/blob/main/.agents/skills/impeccable/SKILL.md","license":"Apache-2.0","relation":"inspired-by"}]}}},"content":"---\nname: canvas-design\ndescription: 在 Loomic 原生画板创作或重排海报、封面和静态视觉；保留可编辑图层，不生成 Python/HTML 来替代画板。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 原生画板设计\n\n从传播目的、画板比例和准确内容确定一个视觉主张，将它落实成焦点、空白和阅读顺序。先用少量对象建立主次，再在必要处增加细节；疏朗、密集、插画或纯文字都由任务决定，不默认少字、不同字体、金色或所谓博物馆风格。\n\n已有画板先读取，再用原生文字、图形、素材与分组组成设计。背景、主体、标题和辅助信息分层；用户只改一处时不重建作品。需要全新画板但当前无创建工具时，请用户创建目标或使用已选空白画板，不假造 design_id。\n\n当需要具体构图或执行字段时读 [构图与原生命令](references/workflow.md)。历史 canvas-fonts 文件不表示字体已进入工作区资源库，不通过 shell、Python 或沙箱输出绕开原生设计交付。\n\n## Loomic 执行边界\n\n只在用户要求实际修改时写入。已绑定任务先合并 goal/corrections；update_design_brief 可用时记录 goal、preserve、changes、acceptance 与真正阻断的 questions。明确小改直接执行，不再开展通用问卷。\n\n使用已绑定的 design_id；未绑定且用户指向已有画板时可用 list_designs 查找。inspect_design 取得 revision 与对象摘要，再用 get_design_objects 读取相关完整对象（每次最多 10 个）。manipulate_design 带最新 expected_revision、idempotency_key；局部 object.update 使用读取到的 object_id、expected_object_version 和 patch.object_type。读取对象为 camelCase，更新 patch 用 snake_case（如 font_size、font_weight），颜色用 {kind:\"solid\",color:\"#…\"}，不能直接套 Fabric 私有字段。\n\n保留未授权对象与属性；不要用 scene.replace、删除重建或 manipulate_canvas 绕过局部编辑。用户修正导致旧任务过期时停止旧操作。最后一次修改后再次核对实际内容差异；verify_design_result 可用时检查当前保存和预览，布局/图片工作用 visual=true，简单改字可 visual=false。视觉不可用、预览未同步、任务仍处理时如实说明，不把版本增加当成功或自动付费重试。\n","files":[{"file_path":"references/workflow.md","content":"# 原生画板设计：按需细则\n\n## 构图决策\n主焦点由尺寸、明暗、空间或位置产生，不要求所有手段同时增强。按用途选择稳定网格、非对称张力或中心识别；同一视线里避免多个同等强度的主角。海报长文不能为构图偷偷删除，必要时扩大区域、缩短经允许的表达或提出篇幅取舍。\n\n## 渲染复核\n画布底色不是最上层可见背景；全幅 rect/image 可覆盖它。判断背景是否改变要同时比较底色和实际背景层。只修真正偏离任务的遮挡、截字、缺图等问题，不把主观建议当作新要求。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"creative-directions","name":"创意方向探索","description":"为开放式设计比较不同概念和视觉组织，解释取舍；已有方向或局部纠正不重新发散。","version":"2.0.0","category":"design","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"guidance","intents":["concept","creative-direction","exploration"],"outputKinds":["design-brief"],"requiredTools":[],"optionalTools":["inspect_design","get_design_objects","update_design_brief","verify_design_result","get_brand_kit"],"models":[{"role":"planner","required":true,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。"],"examples":["给这次发布会想两条区别明显的视觉方向，先不要生成图。"],"sources":[{"title":"SVG concept exploration and small-size inspection","url":"https://github.com/neonwatty/logo-designer-skill/blob/main/skills/logo-designer/SKILL.md","license":"MIT","relation":"inspired-by"},{"title":"Cover art-direction dimensions","url":"https://github.com/JimLiu/baoyu-skills/blob/main/skills/baoyu-cover-image/SKILL.md","license":"MIT","relation":"inspired-by"}]}}},"content":"---\nname: creative-directions\ndescription: 为开放式设计比较不同概念和视觉组织，解释取舍；已有方向或局部纠正不重新发散。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 创意方向探索\n\n先识别传播目的、受众、必须保留的文案/品牌/主体以及可变范围。只在用户允许探索时提供少量有实质差异的路线，要求一版就做一版。\n\n每个方向写清核心记忆点、信息组织、素材需求、适合目标的原因和一个限制。差异应来自概念、轮廓、叙事或构图，不是同一个画面换颜色。用证据推荐而非主观等级词。\n\n概念讨论不调用付费生成。收到选择或局部反馈后停止发散，将仍有效要求保留在当前 brief；不要开启第二轮通用问卷。需要比较框架时读 [方向取舍](references/workflow.md)。\n\n## Loomic 范围\n\n只建议/分析时不调用写入或生成。后续若用户要求落地，使用当前真实目标、工具与模型；update_design_brief 可用时合并仍有效的保留项和最新纠正。已禁用技能、用户权限、目标锁和付费确认不能由本说明绕过。未收到实际图像不声称视觉验收；不存在的工具不能靠提示词补齐。\n","files":[{"file_path":"references/workflow.md","content":"# 创意方向探索：按需细则\n\n## 比较方法\n用同一套固定文案与品牌条件比较，避免某方案通过删除难排内容显得更好。产品主导强调识别，文字主导强调消息，场景叙事强调代入；这是可选思路，不是必须凑齐三版。\n\n每条路线给一个可执行布局描述和资源/预算差异。已有素材够用时说明原生编辑路线；需要新图时只估算所需数量，不自动为所有方案生成样图。若两方案去掉形容词后仍相同，合并而不是保留弱方案。\n\n## 收敛\n选定方向后记录已批准/被否定内容。用户“字再大点”表示深化当前稿，不意味重新讨论品牌。仅分析任务到建议即结束，不调用 manipulate_design。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"design-copywriting","name":"设计文案","description":"把用户提供的品牌和产品事实组织为标题、卖点与行动引导；排版任务不擅自改定稿。","version":"2.0.0","category":"writing","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"guidance","intents":["copywriting","headline","cta"],"outputKinds":["copy","design-brief"],"requiredTools":[],"optionalTools":["inspect_design","get_design_objects","update_design_brief","verify_design_result","get_brand_kit"],"models":[{"role":"planner","required":true,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。"],"examples":["用这些已核实卖点写一个标题和三条短文案，价格不能改。"],"sources":[{"title":"Cover art-direction dimensions","url":"https://github.com/JimLiu/baoyu-skills/blob/main/skills/baoyu-cover-image/SKILL.md","license":"MIT","relation":"inspired-by"},{"title":"Carousel narrative and information density","url":"https://github.com/JimLiu/baoyu-skills/blob/main/skills/baoyu-xhs-images/SKILL.md","license":"MIT","relation":"inspired-by"}]}}},"content":"---\nname: design-copywriting\ndescription: 把用户提供的品牌和产品事实组织为标题、卖点与行动引导；排版任务不擅自改定稿。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 设计文案\n\n先分清已核实事实、用户主张和缺失数据，保留品牌拼写、型号、价格、日期和限制条件。不得补造折扣、销量、认证、效果保证或评价。\n\n围绕受众形成一个主消息，再写支持卖点和具体行动。备选要换表达角度，不只是换形容词；用户已定稿只做排版时不重写。仅要求建议就返回文案，不直接写进画板。\n\n篇幅不足时提出经允许的短版，不以缩短为由删去价格条件。需要实际落字再读取目标文字和版本，只改指定文本对象。读 [准确文案与版面](references/workflow.md) 处理长文和事实占位。\n\n## Loomic 范围\n\n只建议/分析时不调用写入或生成。后续若用户要求落地，使用当前真实目标、工具与模型；update_design_brief 可用时合并仍有效的保留项和最新纠正。已禁用技能、用户权限、目标锁和付费确认不能由本说明绕过。未收到实际图像不声称视觉验收；不存在的工具不能靠提示词补齐。\n","files":[{"file_path":"references/workflow.md","content":"# 设计文案：按需细则\n\n## 准确性清单\n数字连同单位、币种、适用范围、日期时区一起保留；“起”“限量”“仅会员”等不是装饰性文字。未确定信息标成待补，不作为可发布成品。用户只要求润色而未给产品证明时，避免把普通描述升级为功效承诺。\n\n## 版面协作\n标题负责主消息，副文解释依据，CTA 指向真实入口。二维码必须来自真实资源，不凭空生成。字符少不代表不会溢出，最终要在实际字体/宽度上复核。若文案已核准，排版应先调整布局，不能隐式删字。\n\n## 局部写入\n修改前完整读取目标 text，不依赖 inspect 的截断摘要。更新后逐字比较，换行只有在不改变用户准确内容约束时使用；需要重写与用户要求冲突时先澄清。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"design-delivery","name":"多尺寸适配与交付","description":"按现有 PNG/JPEG 导出与原生画板能力适配尺寸、核对保存和预览；不承诺 SVG/PDF/CMYK 输出。","version":"2.0.0","category":"design","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"native","intents":["delivery","export","resize"],"outputKinds":["native-design","raster-export"],"requiredTools":["inspect_design","get_design_objects","manipulate_design"],"optionalTools":["list_designs","update_design_brief","verify_design_result","get_brand_kit","search_design_resources","export_design"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","只使用已存在且获授权的原生画板；当前没有 Agent 自动创建多画板、任意 SVG 路径写入或 SVG/PDF 导出。"],"examples":["将当前设计导出透明 PNG，保留原稿。"],"sources":[{"title":"SVG concept exploration and small-size inspection","url":"https://github.com/neonwatty/logo-designer-skill/blob/main/skills/logo-designer/SKILL.md","license":"MIT","relation":"inspired-by"},{"title":"Reusable theme tokens","url":"https://github.com/anthropics/skills/blob/main/skills/theme-factory/SKILL.md","license":"Apache-2.0","relation":"inspired-by"}]}}},"content":"---\nname: design-delivery\ndescription: 按现有 PNG/JPEG 导出与原生画板能力适配尺寸、核对保存和预览；不承诺 SVG/PDF/CMYK 输出。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 多尺寸适配与交付\n\n读取准确目标及最后 revision，提取用户需要的尺寸、格式、透明性和使用场景，不默认追加版本。尺寸变化要重新组织裁切、留白与文字，不把整图非等比拉伸。\n\nexport_design 当前支持 png/jpeg、multiplier 1 或 2；transparent=true 只用于 PNG，且不代表自动移除图片内背景。job_id/queued 不是文件已完成，要根据实际任务状态交付；没有结果查询工具时明确等待产品任务完成，不捏造下载链接。\n\n原生可编辑设计不同于可编辑 SVG 文件。当前不能承诺 PDF、CMYK、出血、文字转曲或嵌字。详细边界读 [导出与适配](references/workflow.md)。\n\n## Loomic 执行边界\n\n只在用户要求实际修改时写入。已绑定任务先合并 goal/corrections；update_design_brief 可用时记录 goal、preserve、changes、acceptance 与真正阻断的 questions。明确小改直接执行，不再开展通用问卷。\n\n使用已绑定的 design_id；未绑定且用户指向已有画板时可用 list_designs 查找。inspect_design 取得 revision 与对象摘要，再用 get_design_objects 读取相关完整对象（每次最多 10 个）。manipulate_design 带最新 expected_revision、idempotency_key；局部 object.update 使用读取到的 object_id、expected_object_version 和 patch.object_type。读取对象为 camelCase，更新 patch 用 snake_case（如 font_size、font_weight），颜色用 {kind:\"solid\",color:\"#…\"}，不能直接套 Fabric 私有字段。\n\n保留未授权对象与属性；不要用 scene.replace、删除重建或 manipulate_canvas 绕过局部编辑。用户修正导致旧任务过期时停止旧操作。最后一次修改后再次核对实际内容差异；verify_design_result 可用时检查当前保存和预览，布局/图片工作用 visual=true，简单改字可 visual=false。视觉不可用、预览未同步、任务仍处理时如实说明，不把版本增加当成功或自动付费重试。\n","files":[{"file_path":"references/workflow.md","content":"# 多尺寸适配与交付：按需细则\n\n## 透明与画板\ncanvas.update 的 background=null 只改变画布底色，全幅背景 rect/image 仍会显示。export_design transparent=true 是导出设置，不会进行主体抠图，也不授权删除背景层。用户要透明 Logo 时先识别真正背景来源，必要删除仍按确认。\n\n## 尺寸\ncanvas.update 的 resize_mode 为 crop/expand/scale，按用户要求选择；不是一律 scale。多尺寸如果没有另建画板工具，不能通过修改同一目标依次覆盖原稿并声称保留所有版本。用户可以创建副本后按各自授权目标操作。\n\n## 交付核验\n最后写入后 verify_design_result 检查 revision/previewRevision；专业布局还要有实际像素结论。导出待处理就如实报告。输出 PNG/JPEG 不称为矢量，分辨率提升不等于印刷色彩/字体合规。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"design-refinement","name":"反馈与定向修改","description":"将设计反馈映射到局部对象和属性，合并中途纠正并保留已认可内容；不自动重设计。","version":"2.0.0","category":"design","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"native","intents":["refinement","correction","targeted-edit"],"outputKinds":["native-design"],"requiredTools":["inspect_design","get_design_objects","manipulate_design"],"optionalTools":["list_designs","update_design_brief","verify_design_result","get_brand_kit","search_design_resources"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","只使用已存在且获授权的原生画板；当前没有 Agent 自动创建多画板、任意 SVG 路径写入或 SVG/PDF 导出。"],"examples":["刚才说改蓝色，现在只改标题大小，其他保持原样。"],"sources":[{"title":"Bounded design critique","url":"https://github.com/pbakaus/impeccable/blob/main/.agents/skills/impeccable/SKILL.md","license":"Apache-2.0","relation":"inspired-by"},{"title":"SVG concept exploration and small-size inspection","url":"https://github.com/neonwatty/logo-designer-skill/blob/main/skills/logo-designer/SKILL.md","license":"MIT","relation":"inspired-by"}]}}},"content":"---\nname: design-refinement\ndescription: 将设计反馈映射到局部对象和属性，合并中途纠正并保留已认可内容；不自动重设计。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 反馈与定向修改\n\n以当前任务 goal、corrections 和保存状态为准。最新纠正只替换冲突要求，不丢弃仍有效的品牌、准确文案和目标范围。先列本次可改对象/属性与必须保持项，再读真实对象和版本。\n\n“简洁/更有冲击力”需转成有依据的具体变化，如减少竞争、改变标题对比或留白，不只追加形容词。仅有会导致完全不同结果的歧义时澄清，其余说明理解后执行。\n\n优先编辑原生对象。简单改字或移动不需要先加载整套设计流程；不整图重生、不重开方案确认。错误、过期或取消不等于授权重试旧操作。进一步处理读 [纠正与冲突](references/workflow.md)。\n\n## Loomic 执行边界\n\n只在用户要求实际修改时写入。已绑定任务先合并 goal/corrections；update_design_brief 可用时记录 goal、preserve、changes、acceptance 与真正阻断的 questions。明确小改直接执行，不再开展通用问卷。\n\n使用已绑定的 design_id；未绑定且用户指向已有画板时可用 list_designs 查找。inspect_design 取得 revision 与对象摘要，再用 get_design_objects 读取相关完整对象（每次最多 10 个）。manipulate_design 带最新 expected_revision、idempotency_key；局部 object.update 使用读取到的 object_id、expected_object_version 和 patch.object_type。读取对象为 camelCase，更新 patch 用 snake_case（如 font_size、font_weight），颜色用 {kind:\"solid\",color:\"#…\"}，不能直接套 Fabric 私有字段。\n\n保留未授权对象与属性；不要用 scene.replace、删除重建或 manipulate_canvas 绕过局部编辑。用户修正导致旧任务过期时停止旧操作。最后一次修改后再次核对实际内容差异；verify_design_result 可用时检查当前保存和预览，布局/图片工作用 visual=true，简单改字可 visual=false。视觉不可用、预览未同步、任务仍处理时如实说明，不把版本增加当成功或自动付费重试。\n","files":[{"file_path":"references/workflow.md","content":"# 反馈与定向修改：按需细则\n\n## 反馈分类\n文字：只改 text 并核对准确全文。位置：只改 x/y，保留尺寸与颜色。样式：只改授权的字号/颜色/间距。替换图片：要识别目标 image 与源资产，保留原图和其他层；若会付费，由产品确认决定是否入队。\n\n## 并发与中途纠正\ndesign_revision_conflict 表示原读取已过期：重新读取当前对象，对比人工改动，只重新计算仍授权的局部补丁。被 superseded/cancelled 的旧 run 必须结束，不能换 idempotency_key 继续旧任务。相同逻辑请求的状态不明时先查原任务，不能再扣一次费。\n\n## 验证\n不要把 revision 变化当作设计已修改；比较实际属性/文字。最后一次修改之后再次验证保存与预览。用户提出保留项，必须检查未授权图层/属性仍不变；可选审美建议不能扩成额外改动。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"design-review","name":"设计评审","description":"对现有设计做有证据的版式、文字、品牌与用途评审；只点评不写入，简单改字不强制全面评审。","version":"2.0.0","category":"design","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"guidance","intents":["design-review","visual-review","quality"],"outputKinds":["design-review"],"requiredTools":[],"optionalTools":["inspect_design","get_design_objects","update_design_brief","verify_design_result","get_brand_kit"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。"],"examples":["只点评这张活动海报哪里影响阅读，不要修改。"],"sources":[{"title":"Bounded design critique","url":"https://github.com/pbakaus/impeccable/blob/main/.agents/skills/impeccable/SKILL.md","license":"Apache-2.0","relation":"inspired-by"},{"title":"Evidence-based typography review","url":"https://github.com/pbakaus/impeccable/blob/main/.agents/skills/impeccable/reference/typeset.md","license":"Apache-2.0","relation":"inspired-by"}]}}},"content":"---\nname: design-review\ndescription: 对现有设计做有证据的版式、文字、品牌与用途评审；只点评不写入，简单改字不强制全面评审。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 设计评审\n\n先确定用途与用户约束，再读当前设计或实际图像。只拿到 URL、对象坐标或成功状态不能声称已看图；结构事实与视觉事实分开。\n\n检查准确文案、信息层级、遮挡截字、品牌和目标尺寸。优先给最影响任务的少量问题，每项有对象/位置、现象、影响和具体修法。区分客观缺陷、目标相关建议和个人偏好。\n\n只点评不调用写入或生图。要求优化时仅修改授权目标，不把审美建议当强制返工。当前版本的 verify_design_result（若可用）可独立检查预览；复核期间变化使旧结论作废。分类方法读 [评审证据](references/workflow.md)。\n\n## Loomic 范围\n\n只建议/分析时不调用写入或生成。后续若用户要求落地，使用当前真实目标、工具与模型；update_design_brief 可用时合并仍有效的保留项和最新纠正。已禁用技能、用户权限、目标锁和付费确认不能由本说明绕过。未收到实际图像不声称视觉验收；不存在的工具不能靠提示词补齐。\n","files":[{"file_path":"references/workflow.md","content":"# 设计评审：按需细则\n\n## 三类结论\n阻断问题：准确内容错误、清楚可见的截字/严重遮挡、缺失必需资产、明确违反用户硬约束。可选建议：更有张力的构图、更温暖的配色、不同字体偏好；不能因此循环修改。无法确认：像素过小、缺少原参考、字体资源不可读；不能伪装为通过。\n\n## 不误归因\n若权威对比显示画布/图层未变，不把视觉中的既有背景称为本轮新增。底色被全幅图层覆盖时评审可见层，不仅看 canvas.background。结构尺寸不等于真实 glyph 边界，尤其 text 不自动换行。\n\n## 终止条件\n任务约束满足且无客观阻断问题即可交付；不因每轮产生新建议继续改。专业布局优先实际像素复核，简单准确改字可做结构核对。无视觉能力时报告范围，不通过生图来“验证”生图。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"image-layer-separation","name":"图片分层与原生图层","description":"区分原生设计图层编辑与扁平图片分层，为拆分背景、主体、文字等提供当前可执行路径；不将 RGBA 位图拆解冒充原始 PSD 或可编辑字体。","version":"2.0.0","category":"design","iconName":"layers","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"guidance","intents":["image-layer-separation","layer-grouping","rgba-layer-review"],"outputKinds":["operation-guidance","native-layer-edit"],"requiredTools":[],"optionalTools":["inspect_canvas","inspect_design","get_design_objects","manipulate_design","verify_design_result"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]}],"limitations":["扁平图分层目前仅提供当前图片工具栏入口与验收指导；Agent 没有直接 split_layers 工具。","已有原生设计图层可在实际工具和目标权限允许时编辑；位图拆分不能恢复原始 PSD、字体或被遮挡像素。","Qwen-Image-Layered 是后续可选专用引擎，目前未接入；本包不下载模型或调用外部服务。","本包是 Loomic 原创流程，官方模型卡不是本项目效果实测，不能声称分层结果已经通过视觉验收。"],"examples":["把这张扁平海报拆成背景、产品和文字层。","只将画板里现有产品图层与标题分组，其他内容不动。"],"sources":[{"title":"Qwen-Image-Layered 官方模型卡","url":"https://huggingface.co/Qwen/Qwen-Image-Layered","license":"Apache-2.0","relation":"inspired-by"}]}}},"content":"---\nname: image-layer-separation\ndescription: 区分原生设计图层编辑与扁平图片分层，为拆分背景、主体、文字等提供当前可执行路径；不将 RGBA 位图拆解冒充原始 PSD 或可编辑字体。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 图片分层与原生图层\n\n先确认用户指的是已有画板中的真实对象，还是单张扁平图片。对象 ID、源资产与当前目标从实际工具读取，不把截图中看起来独立的元素当作已有图层。\n\n对原生设计，inspect_design 与 get_design_objects 可以读取真实层级，再使用 manipulate_design 在用户指定范围内修改、分组或调整层序。保留字体和其他对象；单纯移动某一层不需要先拆图或重设计。\n\n对扁平图片，当前 Agent 工具没有直接 split_layers 操作。说明可选中原图使用图片工具栏的「图层拆分」，保留源图并检查实际拆分结果。不要调用 generate_image 来冒充分层，不发送不存在的 operation，也不声称已经从 PNG 恢复原始文字、字体、遮挡内容或 PSD。工作区若没有相应入口，直接说明该能力未接入。\n\n此技能的状态为受限指导，不会安装分层模型或服务。只有需要评估新引擎或验收拆分质量时阅读 [分层验收与引擎边界](references/workflow.md)。后续 Qwen-Image-Layered 是可选专用引擎，目前并未接入此 Agent。\n\n只要求建议或检查时不修改对象。执行仍受当前工具、画板目标锁、用户纠正、权限和费用确认约束；技能说明不增加这些权限。\n","files":[{"file_path":"references/workflow.md","content":"# 分层验收与引擎边界\n\n## 验证实际拆分结果\n\n保留原图，记录每层实际尺寸、透明范围、相对位置和层序。将所有结果层按原位置合成后与原图比较，检查主体是否丢失、边缘是否被切碎、阴影和孔洞是否合理，以及重复背景是否影响合成。工具执行成功不等于视觉结果合格；未得到真实结果时只能说明验收方法。\n\n图片里的文字分到透明 PNG 仍是位图，不代表可以改文字或字体。遮挡区域的补全是推测，不能宣称恢复了原始隐藏像素。用户明确要求原始可编辑 PSD、原字体文字或无损恢复时应解释输入限制，并建议提供原始设计文件。\n\n## 后续引擎\n\n[Qwen-Image-Layered 官方模型卡](https://huggingface.co/Qwen/Qwen-Image-Layered) 提供 RGBA 图层拆分的示例。这是研究阶段确认存在的可选模型，不是当前 Loomic Agent 已安装的服务，不将论文指标描述为本项目实测结果。\n\n接入专用引擎应单独评估部署资源、许可、延迟和样本重合成效果，明确用户授权后再实施。本技能不下载模型、不调用外部演示站、不安装 ComfyUI 工作流，也不自动升级本地拆分工具。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"infographic-design","name":"信息图设计","description":"将准确数据、流程和对比关系转成原生文字、图形与箭头；不捏造数值或用随机装饰替代信息结构。","version":"2.0.0","category":"design","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"native","intents":["infographic","comparison","timeline","process"],"outputKinds":["native-design","design-brief"],"requiredTools":["inspect_design","get_design_objects","manipulate_design"],"optionalTools":["list_designs","update_design_brief","verify_design_result","get_brand_kit","search_design_resources"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","只使用已存在且获授权的原生画板；当前没有 Agent 自动创建多画板、任意 SVG 路径写入或 SVG/PDF 导出。"],"examples":["用这组套餐数据做可编辑对比图，不要添加没给的功能。"],"sources":[{"title":"Information relationships before visual styles","url":"https://github.com/JimLiu/baoyu-skills/blob/main/skills/baoyu-infographic/SKILL.md","license":"MIT","relation":"inspired-by"}]}}},"content":"---\nname: infographic-design\ndescription: 将准确数据、流程和对比关系转成原生文字、图形与箭头；不捏造数值或用随机装饰替代信息结构。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 信息图设计\n\n先保留原始文字、数据、单位和来源，再判断信息关系：流程用顺序，套餐用矩阵，分类用层级，循环用回路。先选关系后选风格，不默认所有内容都是 bento 卡片。\n\n将每个节点/标签/连接关系映射为原生 text/textbox、基本形状和 line/arrow，相关内容可分组。真实图表数据没有输入就标缺失，不编造比例、趋势和统计来源。仅要求草图/解释时不写入。\n\n当前没有专业图表引擎或任意路径工具，复杂图形可简化为真实可表达结构，说明缺口；不能交付图片却称所有数据节点可编辑。详细规则读 [结构与图形](references/workflow.md)。\n\n## Loomic 执行边界\n\n只在用户要求实际修改时写入。已绑定任务先合并 goal/corrections；update_design_brief 可用时记录 goal、preserve、changes、acceptance 与真正阻断的 questions。明确小改直接执行，不再开展通用问卷。\n\n使用已绑定的 design_id；未绑定且用户指向已有画板时可用 list_designs 查找。inspect_design 取得 revision 与对象摘要，再用 get_design_objects 读取相关完整对象（每次最多 10 个）。manipulate_design 带最新 expected_revision、idempotency_key；局部 object.update 使用读取到的 object_id、expected_object_version 和 patch.object_type。读取对象为 camelCase，更新 patch 用 snake_case（如 font_size、font_weight），颜色用 {kind:\"solid\",color:\"#…\"}，不能直接套 Fabric 私有字段。\n\n保留未授权对象与属性；不要用 scene.replace、删除重建或 manipulate_canvas 绕过局部编辑。用户修正导致旧任务过期时停止旧操作。最后一次修改后再次核对实际内容差异；verify_design_result 可用时检查当前保存和预览，布局/图片工作用 visual=true，简单改字可 visual=false。视觉不可用、预览未同步、任务仍处理时如实说明，不把版本增加当成功或自动付费重试。\n","files":[{"file_path":"references/workflow.md","content":"# 信息图设计：按需细则\n\n## 关系到布局\n时间线保留时间间隔是否有意义；步骤流程明确分支与方向；对比矩阵固定相同属性行；层级反映真实包含关系，不能把类别误画为排名。数量面积编码必须按真实值，装饰性尺寸不暗示伪比例。\n\n## 原生实现\n矩形、圆、三角形可做节点；line/arrow 定位连接，并使用真实端点坐标，不能杜撰设计对象的自动连接 binding。明确箭头指向和标签位置，分组时 children 对象与 childObjectIds 一致。复杂 Sankey、统计坐标轴或自动数据更新没有工具时不虚构。\n\n## 核对\n逐项对照数据源、单位、负号和条件；检查箭头与所属标签没有串位。密集信息先调整布局或增加经授权的区域，而不是缩到不可读或删数据。最终实际预览核对文字边界和关系可辨性。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"json-image-prompt","name":"图像需求结构化","description":"为确实需要位图生成的任务整理主体、保留项、构图和素材提示；不强制 JSON 格式，也不把改字转成生图。","version":"2.0.0","category":"generation","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"image","intents":["image-prompt","raster-generation"],"outputKinds":["image-prompt","raster-image"],"requiredTools":["generate_image"],"optionalTools":["inspect_design","get_design_objects","update_design_brief","verify_design_result","get_brand_kit","get_image_proposal","confirm_image_generation"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"image","required":true,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。"],"examples":["给产品背景写一个可执行生图提示，准确标题仍用文字层。"],"sources":[{"title":"Cover art-direction dimensions","url":"https://github.com/JimLiu/baoyu-skills/blob/main/skills/baoyu-cover-image/SKILL.md","license":"MIT","relation":"inspired-by"}]}}},"content":"---\nname: json-image-prompt\ndescription: 为确实需要位图生成的任务整理主体、保留项、构图和素材提示；不强制 JSON 格式，也不把改字转成生图。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 图像需求结构化\n\n先确认确实需要新位图，而非文字、位置、颜色等原生命令。整理主体、参考身份、可变范围、构图、光线/材质和必要排除项；只用影响结果的字段，不为所有图片填写相机、天气等无关参数。\n\n结构化是思考与追踪方式，不保证质量更高或重复生成一致。generate_image.prompt 接收字符串，最终写清自然语言需求即可，不添加未支持的 JSON 参数或 --no 命令语法。已有准确文案放原生文字层，不依赖生图拼写。\n\n只使用当前可用模型/schema，尊重用户模型与预算。方案未获产品授权不确认生成，返回 processing 不声称图片已完成。字段与透明边界读 [图像生成协议](references/workflow.md)。\n\n## Loomic 范围\n\n只建议/分析时不调用写入或生成。后续若用户要求落地，使用当前真实目标、工具与模型；update_design_brief 可用时合并仍有效的保留项和最新纠正。已禁用技能、用户权限、目标锁和付费确认不能由本说明绕过。未收到实际图像不声称视觉验收；不存在的工具不能靠提示词补齐。\n","files":[{"file_path":"references/workflow.md","content":"# 图像需求结构化：按需细则\n\n## 可执行参数\ngenerate_image 常用 title、prompt、model、aspectRatio、quality、outputFormat、inputImages。model 必须来自本轮可用列表，不从外部 Skill 固定某版本。quality 为 standard/hd/ultra，分辨率实际取决于供应商能力，不等于印刷验收。\n\n## 参考与落位\n参考真实可访问图像，说明要保留什么以及只改变什么。原生目标使用 target.kind=design、design_id、expected_revision、idempotency_key 与 placement；不要与 placementX/Y 等无限画布旧字段混用。role 如 background/product/logo 必须符合真实用途，不能为绕过抠图改报角色。\n\n当前 schema 没有 transparent 字段；PNG 容器不保证 alpha。非 background 原生图片走平台已有背景处理，不额外触发第二次去背景任务。不可把用户已有图片抠图改成付费生成近似新图。\n\n## 预算与重试\nget_image_proposal 用于读取当前方案，不能猜 confirmationId；confirm_image_generation 只在真实产品确认流程下使用。过期、失败或质量建议不自动授权新增生成，状态不明先追踪原任务。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"logo-design","name":"Logo 与品牌标识","description":"创作或改进 Logo、图形标记和字标，比较识别方向并检查小尺寸；普通海报排版不使用此技能。","version":"2.0.0","category":"design","iconName":"shapes","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"hybrid","intents":["logo","brand-mark","wordmark"],"outputKinds":["native-design","design-brief"],"requiredTools":["inspect_design","get_design_objects","manipulate_design"],"optionalTools":["list_designs","update_design_brief","verify_design_result","get_brand_kit","search_design_resources","generate_image","get_image_proposal","confirm_image_generation"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]},{"role":"image","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","只使用已存在且获授权的原生画板；当前没有 Agent 自动创建多画板、任意 SVG 路径写入或 SVG/PDF 导出。"],"examples":["为咖啡品牌做一个简洁图形加字标，只要一版。"],"sources":[{"title":"SVG concept exploration and small-size inspection","url":"https://github.com/neonwatty/logo-designer-skill/blob/main/skills/logo-designer/SKILL.md","license":"MIT","relation":"inspired-by"},{"title":"Brand rules as reusable constraints","url":"https://github.com/anthropics/skills/blob/main/skills/brand-guidelines/SKILL.md","license":"Apache-2.0","relation":"inspired-by"}]}}},"content":"---\nname: logo-design\ndescription: 创作或改进 Logo、图形标记和字标，比较识别方向并检查小尺寸；普通海报排版不使用此技能。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# Logo 与品牌标识\n\n提取准确名称、使用尺寸、现有识别资产和保留项，缺少关键品牌信息才询问。开放探索可比较几条轮廓与识别逻辑不同的方向；指定一版或已有选择就深化，不强制概念投票。\n\n优先用原生基本图形和独立字标制作能表达概念的标记，已有正式 Logo 使用真实资产。复杂曲线不能靠不存在的 SVG/path 上传工具实现；可说明当前限制并建议用户导入合法 SVG 资源，或在获授权后生成位图概念。位图概念不是矢量母版，展示样机也不是 Logo 本体。\n\n需要探索、单色或小尺寸检查时读 [标识方法](references/workflow.md)。不声称商标检索完成或可注册。\n\n## Loomic 执行边界\n\n只在用户要求实际修改时写入。已绑定任务先合并 goal/corrections；update_design_brief 可用时记录 goal、preserve、changes、acceptance 与真正阻断的 questions。明确小改直接执行，不再开展通用问卷。\n\n使用已绑定的 design_id；未绑定且用户指向已有画板时可用 list_designs 查找。inspect_design 取得 revision 与对象摘要，再用 get_design_objects 读取相关完整对象（每次最多 10 个）。manipulate_design 带最新 expected_revision、idempotency_key；局部 object.update 使用读取到的 object_id、expected_object_version 和 patch.object_type。读取对象为 camelCase，更新 patch 用 snake_case（如 font_size、font_weight），颜色用 {kind:\"solid\",color:\"#…\"}，不能直接套 Fabric 私有字段。\n\n保留未授权对象与属性；不要用 scene.replace、删除重建或 manipulate_canvas 绕过局部编辑。用户修正导致旧任务过期时停止旧操作。最后一次修改后再次核对实际内容差异；verify_design_result 可用时检查当前保存和预览，布局/图片工作用 visual=true，简单改字可 visual=false。视觉不可用、预览未同步、任务仍处理时如实说明，不把版本增加当成功或自动付费重试。\n","files":[{"file_path":"references/workflow.md","content":"# Logo 与品牌标识：按需细则\n\n## 从概念到标记\n先找识别关系：首字母、产品动作、空间负形或品牌故事中的一个核心记忆点。两方案若只是同一轮廓换颜色，不算不同概念。将图形、准确字标与展示背景作为独立对象，保留命名和对象 ID，单次反馈只调整指定比例、颜色或间距。\n\n## 工具边界\n原生有 rect/circle/triangle/line/arrow/group，可做几何标记；没有任意路径布尔运算或文字转轮廓命令。svg 对象引用真实 assetObjectId，不接受 inline SVG。不可把普通图片扩展名改为 .svg 来交付。\n\n## 小尺寸\n用实际预览或可用输出检查图形和字标，不把整条横向组合标压成方形 favicon。可提出单独图标版本，但只有用户要该版本才新建交付物。无实际 16/32px 渲染就说明尚未验证该尺寸；单色检查也不能仅凭彩色大图宣称通过。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"product-visual","name":"商品与产品视觉","description":"制作商品主图、产品场景及卖点图片，优先保护真实产品外形、包装和标识；不编造功效或配件。","version":"2.0.0","category":"design","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"hybrid","intents":["product","ecommerce","product-preservation"],"outputKinds":["native-design","raster-image"],"requiredTools":["inspect_design","get_design_objects","manipulate_design"],"optionalTools":["list_designs","update_design_brief","verify_design_result","get_brand_kit","search_design_resources","generate_image","get_image_proposal","confirm_image_generation"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]},{"role":"image","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","只使用已存在且获授权的原生画板；当前没有 Agent 自动创建多画板、任意 SVG 路径写入或 SVG/PDF 导出。"],"examples":["保持这张瓶身和标签不变，换成干净的促销版式。"],"sources":[{"title":"Cover art-direction dimensions","url":"https://github.com/JimLiu/baoyu-skills/blob/main/skills/baoyu-cover-image/SKILL.md","license":"MIT","relation":"inspired-by"}]}}},"content":"---\nname: product-visual\ndescription: 制作商品主图、产品场景及卖点图片，优先保护真实产品外形、包装和标识；不编造功效或配件。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 商品与产品视觉\n\n从参考素材确定形状、比例、数量、包装、标签和禁止改变项。只看到文件名或 URL 时不声称已看清产品；有身份保真要求却无参考素材时明确限制。\n\n高保真路线优先复用原产品图片，改变独立背景、阴影或原生卖点文字。需要场景生成时传入可访问原图并简短写明保留主体，不用通用外貌描述代替参考。生成编辑仍可能改变标签，不能承诺无损。\n\n原生 image 可调整 fit/crop、几何 mask 和有限 filters，但这些不是主体分割。需要去背景按当前抠图能力处理，不把整图重新生成当作默认方案。详细比较读 [产品保真方法](references/workflow.md)。\n\n## Loomic 执行边界\n\n只在用户要求实际修改时写入。已绑定任务先合并 goal/corrections；update_design_brief 可用时记录 goal、preserve、changes、acceptance 与真正阻断的 questions。明确小改直接执行，不再开展通用问卷。\n\n使用已绑定的 design_id；未绑定且用户指向已有画板时可用 list_designs 查找。inspect_design 取得 revision 与对象摘要，再用 get_design_objects 读取相关完整对象（每次最多 10 个）。manipulate_design 带最新 expected_revision、idempotency_key；局部 object.update 使用读取到的 object_id、expected_object_version 和 patch.object_type。读取对象为 camelCase，更新 patch 用 snake_case（如 font_size、font_weight），颜色用 {kind:\"solid\",color:\"#…\"}，不能直接套 Fabric 私有字段。\n\n保留未授权对象与属性；不要用 scene.replace、删除重建或 manipulate_canvas 绕过局部编辑。用户修正导致旧任务过期时停止旧操作。最后一次修改后再次核对实际内容差异；verify_design_result 可用时检查当前保存和预览，布局/图片工作用 visual=true，简单改字可 visual=false。视觉不可用、预览未同步、任务仍处理时如实说明，不把版本增加当成功或自动付费重试。\n","files":[{"file_path":"references/workflow.md","content":"# 商品与产品视觉：按需细则\n\n## 任务选路\n识别主图：主体完整、产品数量正确、背景不过度竞争。场景图：环境帮助说明使用场景，不添加不存在的附件。细节图：已有素材支持的结构/材质才放大。卖点图：文案与素材事实对应，不能补造认证或测试结果。\n\n## 对照核验\n分别核对瓶盖/边缘/孔洞等结构、标签文字、商标、数量、透视与阴影。原图片保留不等于布局正确，生成成功也不等于外观正确。看不到局部细节时列为无法确认，不给“百分百还原”。系列内固定真实主体与字体角色，不反复重新生成主体来追求一致。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"reference-analysis","name":"参考图分析","description":"从实际参考图提取构图、色彩角色、字体层级和素材关系；只分析不生成，不凭 URL 编造细节。","version":"2.0.0","category":"design","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"guidance","intents":["reference-analysis","visual-analysis"],"outputKinds":["design-brief","design-review"],"requiredTools":[],"optionalTools":["inspect_design","get_design_objects","update_design_brief","verify_design_result","get_brand_kit"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。"],"examples":["参考这两张图的留白和层级，不要照搬标志。"],"sources":[{"title":"Composition and refinement method","url":"https://github.com/anthropics/skills/blob/main/skills/canvas-design/SKILL.md","license":"Apache-2.0","relation":"inspired-by"},{"title":"Cover art-direction dimensions","url":"https://github.com/JimLiu/baoyu-skills/blob/main/skills/baoyu-cover-image/SKILL.md","license":"MIT","relation":"inspired-by"}]}}},"content":"---\nname: reference-analysis\ndescription: 从实际参考图提取构图、色彩角色、字体层级和素材关系；只分析不生成，不凭 URL 编造细节。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 参考图分析\n\n先确认要借鉴和避免的部分，从现有对话获取答案，不重复问卷。多张参考逐一编号，用真实图像输入或可信视觉分析作依据；看不清文字、字体或色值时说明不确定。\n\n将分析分为可见事实、设计推断和迁移建议。重点提取焦点、比例、对比、留白和文字角色之间的关系，不声称从图片识别了精确字体文件或商用许可。\n\n迁移到 Loomic 时提出可以落入原生图层的约束，保留用户品牌与准确文案。只要分析就不调用生成/写入。具体拆解读 [参考到约束](references/workflow.md)。\n\n## Loomic 范围\n\n只建议/分析时不调用写入或生成。后续若用户要求落地，使用当前真实目标、工具与模型；update_design_brief 可用时合并仍有效的保留项和最新纠正。已禁用技能、用户权限、目标锁和付费确认不能由本说明绕过。未收到实际图像不声称视觉验收；不存在的工具不能靠提示词补齐。\n","files":[{"file_path":"references/workflow.md","content":"# 参考图分析：按需细则\n\n## 拆解维度\n焦点：最大/最亮/最留白处在哪里。比例：主体、文字和空白的相对面积。文字：哪些是标题、注释、标签，依靠什么区分。色彩：背景、强调和正文各承担什么任务。材质：哪些需要位图，哪些能原生形状实现。\n\n## 合成参考\n按维度组合，不把图 A 的色彩说成图 B 的特点。参考只是输入，不自动扩大为复制他人独特标记/布局或获取外部资源。让“借鉴留白”变成可检查的空白区域与对象边界，不编造精确像素。\n\n## 能力不足\n截图返回 URL 但模型未收到像素时只能使用已知结构。上传参考缺分辨率时指出不能确认项，不偷偷联网找相似图替代指定参考。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"resource-template-composition","name":"素材与模板编排","description":"选用当前工作区可访问的已发布素材和模板，组合可编辑设计；不把预览 ID 冒充原资产或模板修订。","version":"2.0.0","category":"design","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"native","intents":["resources","template","asset-composition"],"outputKinds":["native-design"],"requiredTools":["inspect_design","get_design_objects","manipulate_design"],"optionalTools":["list_designs","update_design_brief","verify_design_result","get_brand_kit","search_design_resources","apply_design_template"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","只使用已存在且获授权的原生画板；当前没有 Agent 自动创建多画板、任意 SVG 路径写入或 SVG/PDF 导出。","资源搜索摘要不含全部原资产、字体 face 或模板 revision；不猜测这些身份。"],"examples":["使用我的素材库做排版，不要重新生成产品图。"],"sources":[{"title":"Reusable theme tokens","url":"https://github.com/anthropics/skills/blob/main/skills/theme-factory/SKILL.md","license":"Apache-2.0","relation":"inspired-by"},{"title":"Brand rules as reusable constraints","url":"https://github.com/anthropics/skills/blob/main/skills/brand-guidelines/SKILL.md","license":"Apache-2.0","relation":"inspired-by"}]}}},"content":"---\nname: resource-template-composition\ndescription: 选用当前工作区可访问的已发布素材和模板，组合可编辑设计；不把预览 ID 冒充原资产或模板修订。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 素材与模板编排\n\n按用户要求和尺寸检索 search_design_resources，使用当前上下文真实 workspace_id，按 kind/query 缩小范围并按 next_cursor 按需翻页。单页未命中不表示整个库为空。\n\n检索只返回摘要，preview_asset_object_id 不等于原图、字体 face 或模板 revision。只用已得到的真实可插入资产；缺详细元数据时请用户在资源面板选择，不猜 ID。\n\napply_design_template 的 mode=replace 会替换整个设计并要求真实模板修订及产品确认，不是追加素材。用户仅想借局部布局时不要套整模板。字体、素材许可和交付差异读 [资源边界](references/workflow.md)。\n\n## Loomic 执行边界\n\n只在用户要求实际修改时写入。已绑定任务先合并 goal/corrections；update_design_brief 可用时记录 goal、preserve、changes、acceptance 与真正阻断的 questions。明确小改直接执行，不再开展通用问卷。\n\n使用已绑定的 design_id；未绑定且用户指向已有画板时可用 list_designs 查找。inspect_design 取得 revision 与对象摘要，再用 get_design_objects 读取相关完整对象（每次最多 10 个）。manipulate_design 带最新 expected_revision、idempotency_key；局部 object.update 使用读取到的 object_id、expected_object_version 和 patch.object_type。读取对象为 camelCase，更新 patch 用 snake_case（如 font_size、font_weight），颜色用 {kind:\"solid\",color:\"#…\"}，不能直接套 Fabric 私有字段。\n\n保留未授权对象与属性；不要用 scene.replace、删除重建或 manipulate_canvas 绕过局部编辑。用户修正导致旧任务过期时停止旧操作。最后一次修改后再次核对实际内容差异；verify_design_result 可用时检查当前保存和预览，布局/图片工作用 visual=true，简单改字可 visual=false。视觉不可用、预览未同步、任务仍处理时如实说明，不把版本增加当成功或自动付费重试。\n","files":[{"file_path":"references/workflow.md","content":"# 素材与模板编排：按需细则\n\n## 资源身份\nimage/svg 插入需要真实 assetObjectId；font 绑定需要真实 fontFaceId。资源预览只用于比较外观。用户上传不证明商用许可；保留已有来源声明，未知就标记未知。\n\n## 模板\n没有 expected_template_revision 时不能默认 1 或把资源 ID 当作模板 ID。模板覆盖是破坏性工作流，等待产品的真实确认状态；不能通过 scene.replace 绕过。已有定向编辑任务若不允许整板替换，就只编辑原对象。\n\n## 缺失资源\n已知对象引用原图时优先复用它；缺素材提供现有候选或请求补充，不自动变成付费生图。search_design_resources 目前不是下载/导入/字体详情接口；未能插入要说明阻碍，不能声称排版已完成。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"series-visual-design","name":"系列视觉设计","description":"组织多张内容不同但身份一致的成套物料；尺寸适配不重复规划成系列，批量制作遵守目标与预算。","version":"2.0.0","category":"design","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"hybrid","intents":["series","visual-system","multi-design"],"outputKinds":["design-brief","native-design"],"requiredTools":["inspect_design","get_design_objects","manipulate_design"],"optionalTools":["list_designs","update_design_brief","verify_design_result","get_brand_kit","search_design_resources","generate_image","get_image_proposal","confirm_image_generation"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]},{"role":"image","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","只使用已存在且获授权的原生画板；当前没有 Agent 自动创建多画板、任意 SVG 路径写入或 SVG/PDF 导出。"],"examples":["把已有三张发布海报统一字体层级，保留各自内容。"],"sources":[{"title":"Reusable theme tokens","url":"https://github.com/anthropics/skills/blob/main/skills/theme-factory/SKILL.md","license":"Apache-2.0","relation":"inspired-by"},{"title":"Carousel narrative and information density","url":"https://github.com/JimLiu/baoyu-skills/blob/main/skills/baoyu-xhs-images/SKILL.md","license":"MIT","relation":"inspired-by"}]}}},"content":"---\nname: series-visual-design\ndescription: 组织多张内容不同但身份一致的成套物料；尺寸适配不重复规划成系列，批量制作遵守目标与预算。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 系列视觉设计\n\n从已授权任务确认张数、每张内容和真实目标画板，不擅自加交付物。统一品牌、字体角色、配色和图像语言，同时让各张承担不同消息，不能只换颜色凑数量。\n\n制作前简短对应每张主题、准确文案、素材、尺寸与实际 design_id。已有批准方向直接扩展；探索型大批量可建议先看代表稿，但不重设产品付费确认。\n\n绑定单画板任务不能跨到其他设计。当前没有创建整套画板的 Agent 工具时，先完成已绑定项，并说明其余需要创建/选择目标，不能以计划冒充成品。系列细则读 [系列矩阵](references/workflow.md)。\n\n## Loomic 执行边界\n\n只在用户要求实际修改时写入。已绑定任务先合并 goal/corrections；update_design_brief 可用时记录 goal、preserve、changes、acceptance 与真正阻断的 questions。明确小改直接执行，不再开展通用问卷。\n\n使用已绑定的 design_id；未绑定且用户指向已有画板时可用 list_designs 查找。inspect_design 取得 revision 与对象摘要，再用 get_design_objects 读取相关完整对象（每次最多 10 个）。manipulate_design 带最新 expected_revision、idempotency_key；局部 object.update 使用读取到的 object_id、expected_object_version 和 patch.object_type。读取对象为 camelCase，更新 patch 用 snake_case（如 font_size、font_weight），颜色用 {kind:\"solid\",color:\"#…\"}，不能直接套 Fabric 私有字段。\n\n保留未授权对象与属性；不要用 scene.replace、删除重建或 manipulate_canvas 绕过局部编辑。用户修正导致旧任务过期时停止旧操作。最后一次修改后再次核对实际内容差异；verify_design_result 可用时检查当前保存和预览，布局/图片工作用 visual=true，简单改字可 visual=false。视觉不可用、预览未同步、任务仍处理时如实说明，不把版本增加当成功或自动付费重试。\n","files":[{"file_path":"references/workflow.md","content":"# 系列视觉设计：按需细则\n\n## 系列矩阵\n每项记录用途、核心消息、共用 token、差异变量与目标 ID。叙事轮播按阅读顺序组织；发布物料可各自独立。相同内容只是尺寸不同，应重排构图而不是复制成新消息。\n\n## 一致性\n共用确定的字体/颜色/产品资产，比每张图片参考上一张再生成更可控。位图只用于必要素材，文字和序号保持原生可改。不能为了风格一致把准确 Logo/产品重新画一遍。\n\n## 完成状态\n逐项记录已保存、生成处理中、失败、未开始和待验证。一次成功不代表整组通过；超时查原任务，不整批重跑。真实目标不在授权范围时停止该项，不能把对象写进相邻画板。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"social-carousel","name":"社交轮播图","description":"按滑动阅读顺序组织社交轮播的封面、内容卡和结尾，统一原生文字与版式；普通单张海报不扩成系列。","version":"2.0.0","category":"design","iconName":"palette","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"hybrid","intents":["carousel","social-carousel","xiaohongshu"],"outputKinds":["design-brief","native-design"],"requiredTools":["inspect_design","get_design_objects","manipulate_design"],"optionalTools":["list_designs","update_design_brief","verify_design_result","get_brand_kit","search_design_resources","generate_image","get_image_proposal","confirm_image_generation"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]},{"role":"image","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","只使用已存在且获授权的原生画板；当前没有 Agent 自动创建多画板、任意 SVG 路径写入或 SVG/PDF 导出。"],"examples":["将这五条事实整理为四张可编辑轮播，先给分页计划。"],"sources":[{"title":"Carousel narrative and information density","url":"https://github.com/JimLiu/baoyu-skills/blob/main/skills/baoyu-xhs-images/SKILL.md","license":"MIT","relation":"inspired-by"},{"title":"Reusable theme tokens","url":"https://github.com/anthropics/skills/blob/main/skills/theme-factory/SKILL.md","license":"Apache-2.0","relation":"inspired-by"}]}}},"content":"---\nname: social-carousel\ndescription: 按滑动阅读顺序组织社交轮播的封面、内容卡和结尾，统一原生文字与版式；普通单张海报不扩成系列。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 社交轮播图\n\n按用户指定平台、顺序、张数和事实组织阅读体验：封面给读者明确收益，内容卡各承担一个任务，结尾只在需要时给真实行动入口。已有张数优先，不强制固定页数或三套方案。\n\n根据信息选择故事推进、直接结论加证据或视觉先行；页面密度和节奏服务内容，不把所有页塞进同一模板。字体、颜色、序号与边距由共用 token 控制，准确文字保留原生层。\n\n单任务绑定目标不允许跨画板写入；当前无创建多画板工具时先提供分页计划或处理指定页，请用户建立/选择其余目标。未经预算授权不批量生成。需要分页与一致性时读 [轮播方法](references/workflow.md)。\n\n## Loomic 执行边界\n\n只在用户要求实际修改时写入。已绑定任务先合并 goal/corrections；update_design_brief 可用时记录 goal、preserve、changes、acceptance 与真正阻断的 questions。明确小改直接执行，不再开展通用问卷。\n\n使用已绑定的 design_id；未绑定且用户指向已有画板时可用 list_designs 查找。inspect_design 取得 revision 与对象摘要，再用 get_design_objects 读取相关完整对象（每次最多 10 个）。manipulate_design 带最新 expected_revision、idempotency_key；局部 object.update 使用读取到的 object_id、expected_object_version 和 patch.object_type。读取对象为 camelCase，更新 patch 用 snake_case（如 font_size、font_weight），颜色用 {kind:\"solid\",color:\"#…\"}，不能直接套 Fabric 私有字段。\n\n保留未授权对象与属性；不要用 scene.replace、删除重建或 manipulate_canvas 绕过局部编辑。用户修正导致旧任务过期时停止旧操作。最后一次修改后再次核对实际内容差异；verify_design_result 可用时检查当前保存和预览，布局/图片工作用 visual=true，简单改字可 visual=false。视觉不可用、预览未同步、任务仍处理时如实说明，不把版本增加当成功或自动付费重试。\n","files":[{"file_path":"references/workflow.md","content":"# 社交轮播图：按需细则\n\n## 分页\n封面说明主题及看完收益，不编造夸张数字。中间按问题→解释→证据，或结论→对比→建议组织；一页一任务不是强制一页一句话。保留数据、必要条件和语义，不能为视觉简洁删掉关键事实。结尾不必永远是促销，可以总结或提示下一步。\n\n## 密度与节奏\n封面通常更疏朗；列表页、对比页按数据关系选布局，间隔留出呼吸空间。序号与阅读方向一致，色彩区分章节但不让每页像不同品牌。用原生 textbox/形状/图像组合，不把整页准确文字烧成不可编辑图片。\n\n## 局部纠正\n用户只改第三页标题，就只改对应真实对象；保留其他页、顺序、图片和token。付费图像素材失败不整批重跑；逐页核对实际保存与预览，未建立的画板不标成完成。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]},{"manifest":{"slug":"typography-layout","name":"字体与版式","description":"为设计画板建立文字层级、网格、对齐和留白，处理长标题与中英文混排；简单改字无需全面排版。","version":"2.0.0","category":"design","iconName":"type","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"native","intents":["typography","layout","hierarchy"],"outputKinds":["native-design"],"requiredTools":["inspect_design","get_design_objects","manipulate_design"],"optionalTools":["list_designs","update_design_brief","verify_design_result","get_brand_kit","search_design_resources"],"models":[{"role":"planner","required":true,"preferredIds":[]},{"role":"vision","required":false,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","只使用已存在且获授权的原生画板；当前没有 Agent 自动创建多画板、任意 SVG 路径写入或 SVG/PDF 导出。"],"examples":["不改字和颜色，只改善这两段文字的字号层级与间距。"],"sources":[{"title":"Evidence-based typography review","url":"https://github.com/pbakaus/impeccable/blob/main/.agents/skills/impeccable/reference/typeset.md","license":"Apache-2.0","relation":"inspired-by"},{"title":"Composition and refinement method","url":"https://github.com/anthropics/skills/blob/main/skills/canvas-design/SKILL.md","license":"Apache-2.0","relation":"inspired-by"}]}}},"content":"---\nname: typography-layout\ndescription: 为设计画板建立文字层级、网格、对齐和留白，处理长标题与中英文混排；简单改字无需全面排版。\nmetadata:\n  author: loomic\n  version: \"2.0.0\"\n---\n\n# 字体与版式\n\n先读取真实文字、字体绑定、尺寸和对象版本，保留用户批准的内容、字体及颜色。根据阅读目的建立标题、正文、注释等必要角色；用字号、字重、间距与对齐共同形成主次，不为“专业”强行更换字体。\n\n绑定 fontFaceId 优先于字体名称。沿用字体仅改字号/字重时保留绑定；确需换字体系，必须取得真实可用 font_face_id 或明确说明取消绑定并使用可用回退的影响。不把搜索预览 ID 当字体 ID。\n\ntext 不会因 width 自动换行，长文按真实类型处理；禁止用对象宽度推断实际字形未出界。字体/字段/换行细则读 [排版执行](references/workflow.md)。\n\n## Loomic 执行边界\n\n只在用户要求实际修改时写入。已绑定任务先合并 goal/corrections；update_design_brief 可用时记录 goal、preserve、changes、acceptance 与真正阻断的 questions。明确小改直接执行，不再开展通用问卷。\n\n使用已绑定的 design_id；未绑定且用户指向已有画板时可用 list_designs 查找。inspect_design 取得 revision 与对象摘要，再用 get_design_objects 读取相关完整对象（每次最多 10 个）。manipulate_design 带最新 expected_revision、idempotency_key；局部 object.update 使用读取到的 object_id、expected_object_version 和 patch.object_type。读取对象为 camelCase，更新 patch 用 snake_case（如 font_size、font_weight），颜色用 {kind:\"solid\",color:\"#…\"}，不能直接套 Fabric 私有字段。\n\n保留未授权对象与属性；不要用 scene.replace、删除重建或 manipulate_canvas 绕过局部编辑。用户修正导致旧任务过期时停止旧操作。最后一次修改后再次核对实际内容差异；verify_design_result 可用时检查当前保存和预览，布局/图片工作用 visual=true，简单改字可 visual=false。视觉不可用、预览未同步、任务仍处理时如实说明，不把版本增加当成功或自动付费重试。\n","files":[{"file_path":"references/workflow.md","content":"# 字体与版式：按需细则\n\n## 文字角色\n先找主次混淆在哪里，再调角色之间的比例。小画板优先减少竞争而非无限缩字。中英文实际字形的字重、基线和密度可能不同，不能只按字符数估计宽度。长标题保留准确文案，可调整宽度、字号、位置；需要显式换行时保留语义并核对全文。\n\n## 类型与字段\nget_design_objects 返回 fontSize/fontWeight/fontFaceId 等 camelCase 对象；object.update.patch 使用 object_type、font_size、font_weight、font_face_id、font_family、line_height、char_spacing、text_align 等 snake_case 字段。object_type 必须等于读取到的 text 或 textbox，不靠 patch 改对象类型。\n\ntext 的边界以实际字形为准；textbox 有自动换行，width/line_height 改动会影响高度。需要从 text 改 textbox 时属于替换对象，不能偷偷把小改扩展为删除重建。先用当前类型可行的办法；确需替换按工具确认。\n\n## 复核\n保存后逐字核对全文、绑定字体和本轮真实属性差异；布局/字体工作用最后版本的 verify_design_result visual=true（工具可用时）。实际预览检查左右边距、上下截字、重叠、缺字；视觉不可用就说明待核验，不宣称已经像素验收。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]}]$design_catalog_01dda70a2b759564$::jsonb;
  entry jsonb;
  file_entry jsonb;
  target_id uuid;
BEGIN
  -- Lock existing rows before ownership checks. A competing slug INSERT is
  -- checked again by the guarded UPSERT below, so it cannot grant ownership.
  PERFORM 1 FROM public.skills AS s
    WHERE s.slug IN (SELECT item->'manifest'->>'slug' FROM jsonb_array_elements(entries) AS item)
    ORDER BY s.slug FOR UPDATE;
  IF EXISTS (
    SELECT 1 FROM public.skills AS s
    WHERE s.slug IN (SELECT item->'manifest'->>'slug' FROM jsonb_array_elements(entries) AS item)
      AND (s.source IS DISTINCT FROM 'system' OR s.created_by IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'Design skill catalog conflicts with a non-owned skill; nothing was changed';
  END IF;

  FOR entry IN SELECT value FROM jsonb_array_elements(entries) LOOP
    target_id := NULL;
    INSERT INTO public.skills AS owned (slug, name, description, author, version, license, category, icon_name, source, skill_content, metadata, is_featured)
    VALUES (entry->'manifest'->>'slug', entry->'manifest'->>'name', entry->'manifest'->>'description', 'Loomic',
      entry->'manifest'->>'version', entry->'manifest'->>'license', entry->'manifest'->>'category',
      entry->'manifest'->>'iconName', 'system', entry->>'content', entry->'manifest'->'metadata', true)
    ON CONFLICT (slug) DO UPDATE SET
      name = EXCLUDED.name, description = EXCLUDED.description, author = EXCLUDED.author,
      version = EXCLUDED.version, license = EXCLUDED.license, category = EXCLUDED.category,
      icon_name = EXCLUDED.icon_name, skill_content = EXCLUDED.skill_content,
      metadata = COALESCE(owned.metadata, '{}'::jsonb) || EXCLUDED.metadata, updated_at = now()
    WHERE owned.source = 'system' AND owned.created_by IS NULL
    RETURNING id INTO target_id;
    IF target_id IS NULL THEN
      RAISE EXCEPTION 'Design skill ownership changed concurrently; nothing was changed';
    END IF;
    FOR file_entry IN SELECT value FROM jsonb_array_elements(entry->'files') LOOP
      INSERT INTO public.skill_files (skill_id, file_path, content, mime_type)
      VALUES (target_id, file_entry->>'file_path', file_entry->>'content', file_entry->>'mime_type')
      ON CONFLICT (skill_id, file_path) DO UPDATE SET
        content = EXCLUDED.content, mime_type = EXCLUDED.mime_type, updated_at = now();
    END LOOP;
  END LOOP;
END;
$design_catalog_migration$;
